// Check each task for files
const tasks = $input.first().json.result || [];
console.log(`Found ${tasks.length} tasks total`);

const tasksWithDetails = tasks.map(task => ({
  task_id: task.id,
  title: task.title,
  description: task.description
}));

if (tasksWithDetails.length === 0) {
  console.log('No tasks found!');
  return [{ json: { message: 'No tasks found in Kanboard' } }];
}

console.log('Tasks found:');
tasksWithDetails.forEach(task => {
  console.log(`- Task ${task.task_id}: ${task.title}`);
});

// Return all tasks for file checking
return tasksWithDetails.map(task => ({ json: task }));

// Analyze files for each task
const taskData = $input.first().json;
const filesData = $input.last().json;

const files = filesData.result || [];

console.log(`\n=== TASK ${taskData.task_id}: ${taskData.title} ===`);
console.log(`Files found: ${files.length}`);

if (files.length === 0) {
  console.log('No files attached to this task');
  return {
    json: {
      task_id: taskData.task_id,
      task_title: taskData.title,
      files_count: 0,
      files: [],
      message: 'No files attached'
    }
  };
}

// Analyze each file
const fileDetails = files.map(file => {
  console.log(`File: ${file.name}`);
  console.log(`- ID: ${file.id}`);
  console.log(`- Size: ${file.size} bytes`);
  console.log(`- MIME: ${file.mimetype || 'unknown'}`);
  console.log(`- Token: ${file.token}`);
  console.log(`- Date: ${file.date}`);

  return {
    id: file.id,
    name: file.name,
    size: file.size,
    mimetype: file.mimetype,
    token: file.token,
    download_url: `/index.php?controller=FileController&action=download&file_id=${file.id}&token=${file.token}`,
    is_pdf: file.name && file.name.toLowerCase().endsWith('.pdf')
  };
});

const pdfFiles = fileDetails.filter(f => f.is_pdf);
console.log(`PDF files: ${pdfFiles.length}`);

return {
  json: {
    task_id: taskData.task_id,
    task_title: taskData.title,
    files_count: files.length,
    pdf_count: pdfFiles.length,
    files: fileDetails,
    pdf_files: pdfFiles
  }
};
